import{_ as r,o as d,c as p,ag as e}from"./chunks/framework.DUTPmUpA.js";const a="/_assets/chIqYgk.YWbxQAWo.jpg",s="/_assets/lIl4maG.A-_-JSbm.jpg",o="/_assets/y3wMAMp.BIneMTHY.png",b="/_assets/aFNmLNT.elFI79n9.png",i="/_assets/7qvk253.BIKB9rV4.png",n="/_assets/VhuUzL9.DHh1mnU4.png",h="/_assets/ioODWyt.BCAAZogy.png",l="/_assets/ajnc7uu.CaM6SA3p.png",A=JSON.parse('{"title":"Падающий лепесток вишни для частицы весеннего настроения","description":"","frontmatter":{"title":"Падающий лепесток вишни для частицы весеннего настроения","author":"kritth","steamId":"76561198055627364","date":"05.02.2015"},"headers":[],"relativePath":"assets/particles/falling-cherry-blossom-petal-for-spring-mood-particle.md","filePath":"assets/particles/falling-cherry-blossom-petal-for-spring-mood-particle.md"}'),c={name:"assets/particles/falling-cherry-blossom-petal-for-spring-mood-particle.md"};function m(_,t,g,y,f,u){return d(),p("div",null,[...t[0]||(t[0]=[e('<p>Падающий лепесток вишни для частицы весеннего настроения</p><p> Если вы новичок в создании частиц, вам следует прочитать <a href="particle-basics">эта базовая частица</a> сначала, потому что я не буду объяснять эти функции подробно. Вместо этого я объясню мыслительный процесс, который приходит мне в голову во время каждого творения. Теперь давайте начнем. </p><p>I на днях работал над своей картой на следующем изображении. </p><img src="'+a+'"><p> Мне кажется, ему не хватает какого-то «весеннего» настроения. Так что я чувствую, что должен быть лепесток падая вниз. Поскольку это довольно просто сделать, я чувствую, что мне следует включить это в качестве примера в учебник. Конечный результат будет похож на следующее изображение. На статичном изображении вы можете мало что увидеть, но после того, как вы закончите, на вашей карте начнут летать эти лепестки. </p><img src="'+s+'"><p> Если вы знаете, что делать, вы можете просто добавить эти функции в свою систему. Я также объясню в подробно о моем мыслительном процессе, а также о шагах по его созданию. </p> ``` lua Render sprites Lifespan decay Alpha fade out simple Movement basic Rotation basic Noise vector Rotation spin roll Radius scale Alpha fade in simple Rotation random Position within sphere random Alpha random Lifetime random Radius random Emit continuously ``` <p>Теперь, если вы хотите узнать более подробную информацию об этой системе, </p> - открыть редактор частиц <br> - создать новую частицу. <p>Теперь я хочу, чтобы лепестки отображались. </p> - Добавьте <b> &quot;Render Sprites&quot; </b> в Renderer, так как его нет самоанимация, задействованная в этой системе. <br> - Теперь я проверяю тип ориентации, он уже установлен на «Выравнивание экрана», так что все готово. <br> — Прокрутите вниз до поля текстуры, вы увидите спрайт круга. <p> Но для этой ситуации мне нужен спрайт лепестка, падающий круг может работать как снег, но не на весну. </p> - Нажмите на увеличительное стекло, чтобы открыть браузер. <br>. На этом этапе вы можете использовать свой собственный материал vtex в качестве текстуры, но в этом уроке материалы/частица/цветок/цветок.vtex выполнит эту работу. <p>Теперь, когда рендерер включен, мне нужен эмиттер, чтобы показать мой лепесток. </p> — добавить <b> «Emit Continuous» </b> в Emitter, так как я хочу, чтобы мои лепестки продолжали падать. <p><b> Не забудьте изменить максимальное количество частиц в базовых свойствах и уровень выбросов. соответственно, чтобы ваша система частиц не переполнялась слишком большим количеством частиц. </b> В этом уроке я установил значение 160, так как считаю, что этого должно хватить. Теперь на вашем экране должно быть что-то похожее на это. </p><img src="'+o+'"><p> Теперь, когда он показывает лепесток, но пока ничего не происходит. Поскольку я хочу, чтобы эти лепестки двигались и исчезают в некоторых моментах, я перехожу к следующему шагу: </p> - Добавьте <b> &quot;Lifespan Decay&quot; </b> в Операторе, так как я хочу, чтобы они исчезали в некоторые моменты. <br> — Добавьте <b> «Базовое движение» </b> в Операторе, так как я хочу, чтобы они двигались в некоторых точках. <p> Теперь я чувствую, что этой сцене нужна гравитация, поскольку в некоторых местах лепесток будет падать. направления. Поэтому я вношу некоторые изменения в значение в базовом движении следующим образом: </p><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>гравитация</td><td>100 -100 -200</td></tr><tr><td>перетащить</td><td>-0,4</td></tr></tbody></table><p> Гравитацию можно свободно регулировать по своему вкусу, но мне нравится, когда я двигаюсь в этом направлении. Ваш результат должен быть чем-то похожим на этот. </p><img src="'+b+'"><p> Теперь лепестки появляются и движутся под действием силы тяжести, я хочу, чтобы они распространились по всей области. не просто начать с начала. Поэтому я делаю это </p> - Добавьте <b> «Положение внутри сферы случайно» </b> в инициализаторе, чтобы расположить мои лепестки. <p>Теперь существует два подхода к инициализации этой функции. </p> - Первый способ — вручную настроить значение в редакторе частиц. <br> - Второй способ - привязать его к контрольной точке. <p> Я объясню первый способ, поскольку буду использовать его статически в молотке (регулируя эти элементы управления). очки в молотке это ад.) </p><p> Теперь я хочу, чтобы они стартовали в определенном радиусе и с определенной скоростью. Я меняю следующее ценности. </p><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>расстояние мин</td><td>0,0</td></tr><tr><td>расстояние макс</td><td>1500.0 (максимальный радиус, который вы хотите покрыть)</td></tr><tr><td>абсолютное значение смещения расстояния</td><td>0.0 0.0 0.7 (поскольку я хочу, чтобы они появлялись только в верхней половине сферы)</td></tr><tr><td>скорость мин</td><td>10</td></tr><tr><td>максимальная скорость</td><td>10</td></tr><tr><td>скорость в местной системе координат min</td><td>0 0 -20</td></tr><tr><td>скорость в местной системе координат max</td><td>0 0 -20</td></tr></tbody></table><p> Если вы хотите привязать эти значения к контрольной точке, просто измените <b>scale CP</b>, в котором (x, y, z) будет представлять (расстояние, скорость, местную скорость) желаемую контрольную точку и устанавливать все вышеперечисленное. значение до 1,0, за исключением минимального расстояния и абсолютного значения смещения расстояния. Теперь, когда это сделано, вам следует увидеть что-то похожее на следующее. </p><img src="'+i+'"><p> Теперь я чувствую, что этим лепесткам не хватает естественности. Поэтому я добавляю случайность в эту систему с помощью следующие функции. </p> - Добавьте <b> «Случайное вращение» </b> в инициализатор. <br> — добавить <b> «Альфа-случайный» </b> в инициализатор. <br> — добавить <b> «случайный случай на всю жизнь» </b> в инициализатор. <br> — добавить <b> «Случайный радиус» </b> в инициализатор. <p> Теперь вам предстоит зайти в каждую функцию и настроить значение на свой вкус. Ниже приведены настройки, которые я использую в этом уроке. </p><h4>Вращение случайное</h4> - значение по умолчанию <h4>Альфа-случайный</h4><p> Людям не понравится, если эти лепестки будут закрывать обзор игрокам, поэтому я установил значения как следует. </p><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>альфа мин</td><td>100</td></tr><tr><td>альфа макс</td><td>150</td></tr></tbody></table><h4>Случайное время жизни</h4><p> Лепестки должны исчезнуть в разное время, поэтому я установил следующие значения: </p> | Поле | Значение | | ------------ | ----- | | срок службы мин | 1,5 | | максимальный срок службы | 3.0 | <h4>Радиус случайный</h4><p>На самом деле лепестки не везде одинакового размера, поэтому я установил следующие значения: </p><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>радиус мин</td><td>10,0</td></tr><tr><td>радиус макс</td><td>20,0</td></tr></tbody></table><p>После того, как все эти параметры установлены, вы должны увидеть результат, аналогичный показанному ниже. </p><img src="'+n+'"><p> Теперь, когда вы видите случайность при создании, но внезапное появление и исчезновение меня немного раздражает. Итак Я избавляюсь от них: </p> - Добавьте <b> «Альфа-фейд просто» </b> в Операторе. <br> — Добавьте <b> «Простое затухание альфа-канала» </b> в Операторе. <p> Я оставил это значение по умолчанию, так как считаю, что оно уже намного лучше, чем раньше. Вы можете свободно отрегулируйте эти значения по своему усмотрению. </p><p> Теперь лепестки падают, появляются и исчезают, мы хотим, чтобы они вращались при движении, чтобы это выглядело лучше. натуральный. Для этого добавьте следующую функцию. </p> - Добавьте <b> «Basic Rotation» </b> в Операторе. <br> — Добавьте <b> «Вращающийся вращение» </b> в Операторе. <p>А теперь отрегулируйте значения вращения вращения и оставьте базовое вращение по умолчанию. </p><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>степень скорости вращения</td><td>10,0</td></tr></tbody></table><p> Итак, теперь лепестки начинают вращаться, я хочу, чтобы они становились меньше по мере того, как они идут, чтобы уменьшить некоторые блокируя обзор игрокам. Поэтому я добавляю: </p> - Добавьте <b> «Шкала радиуса» </b> в Операторе. <p> Однако я не хочу, чтобы они начинались сразу, а лепестки не возвращались к масштабу 0,0, поэтому Я настраиваю следующие значения: </p> | Поле | Значение | | ------------------ | ----- | | время начала | 0,5 | | время окончания | 1.0 | | начальная шкала радиуса | 1.0 | | конечная шкала радиуса | 0,4 | <p>Теперь у вас должно получиться что-то похожее на это. </p><img src="'+h+'"><p> Теперь это выглядит почти естественно, но здесь нет ветра. Обычно, когда лепестки падают, это должно несколько подвергаться воздействию ветра. Для этого я добавляю следующую функцию: </p> - Добавьте <b> «Вектор шума» </b> в Оператор. <p> Теперь вы должны увидеть, как ваши лепестки мигают разными цветами. Не паникуйте. Мы не корректировали значение еще не установлено, поэтому оно установлено по умолчанию. Теперь я хочу настроить так, чтобы шум добавлялся в мою спрайт, как это происходит со случайностью. Поэтому я установил следующие значения: </p><table tabindex="0"><thead><tr><th>Поле</th><th>Значение</th></tr></thead><tbody><tr><td>поле вывода</td><td>Позиция</td></tr><tr><td>минимум вывода</td><td>-10,0 -10,0 -10,0</td></tr><tr><td>максимальный выход</td><td>10,0 10,0 10,0</td></tr><tr><td>масштаб координат шума</td><td>0,2</td></tr><tr><td>добавка</td><td>правда</td></tr></tbody></table><p> Теперь ваши падающие лепестки должны выглядеть очень естественно, и вы можете настроить все эти значения. как вы желаете. Частицы результата должны быть похожи на следующие. </p><img src="'+l+'"><p>Это руководство подходит к концу.</p>',121)])])}const R=r(c,[["render",m]]);export{A as __pageData,R as default};
